import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // current: largest valid ring whose values end at the current value.
        long best = 0, current = 0, previous = -2, previousCount = 0;
        for (int i = 0, j; i < n; i = j) {
            for (j = i; j < n && a[j] == a[i]; j++) {}
            long value = a[i], count = j - i;
            if (value != previous + 1) current = count;
            else if (previousCount == 1) current = previousCount + count; // a single copy can only be an end
            else current += count;
            best = Math.max(best, current);
            previous = value;
            previousCount = count;
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Ints(a)
	// current: largest valid ring whose values end at the current value.
	best, current, previous, previousCount := 0, 0, -2, 0
	for i := 0; i < n; {
		j := i
		for j < n && a[j] == a[i] {
			j++
		}
		value, count := a[i], j-i
		if value != previous+1 {
			current = count
		} else if previousCount == 1 {
			current = previousCount + count // a single copy can only be an end
		} else {
			current += count
		}
		best = max(best, current)
		previous, previousCount = value, count
		i = j
	}
	fmt.Println(best)
}
